<?php
declare(strict_types=1);
$host=getenv('DB_HOST')?:'127.0.0.1';$port=getenv('DB_PORT')?:'3306';$name=getenv('DB_NAME')?:'lirandzu';$user=getenv('DB_USER')?:'root';$pass=getenv('DB_PASS')?:'';
$pdo=new PDO("mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$tables=['users','categories','providers','provider_applications','service_requests','request_messages','customer_profiles','provider_categories','provider_services','provider_media','provider_application_categories','request_status_history','notifications','audit_logs','auth_rate_limits'];$existing=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);foreach($tables as $table){if(!in_array($table,$existing,true)){fwrite(STDERR,"Missing table: {$table}\n");exit(1);}}
$columns=$pdo->query("SHOW COLUMNS FROM users LIKE 'role'")->fetch();if(!$columns||!str_contains((string)$columns['Type'],"'customer'")){fwrite(STDERR,"users.role does not support customer accounts\n");exit(1);}
$count=(int)$pdo->query('SELECT COUNT(*) FROM categories')->fetchColumn();if($count<8){fwrite(STDERR,"Expected at least 8 seed categories, found {$count}\n");exit(1);}
$required=['providers'=>['province','district','website_url','instagram_url'],'service_requests'=>['customer_user_id','assigned_admin_id','event_province','closed_at'],'request_messages'=>['delivery_target','moderated_by'],'provider_applications'=>['reviewed_by']];foreach($required as $table=>$fields){$found=$pdo->query("SHOW COLUMNS FROM `".$table."`")->fetchAll(PDO::FETCH_COLUMN);foreach($fields as $field){if(!in_array($field,$found,true)){fwrite(STDERR,"Missing column {$table}.{$field}\n");exit(1);}}}
echo "LIRANDZU database migration integration checks passed.\n";
